def build_memories(memories: list[tuple[int, str]]) -> str:
    lines = "\n".join(f"[{memory_id}] {text}" for memory_id, text in memories)
    return f"{MEMORIES_PREFIX}\n{lines or 'Поки нічого.'}\n</memories>"


def reply_language(text: str) -> str:
    if CYRILLIC.search(text) or not LATIN.search(text):
        return "Ukrainian"
    return "Polish" if POLISH.search(text) else "English"


def build_context(timezone: str, text: str = "", now: datetime | None = None, owner: str | None = None) -> str:
    local = (now or datetime.now(ZoneInfo(timezone))).astimezone(ZoneInfo(timezone))
    context = f"Now: {local:%Y-%m-%d %H:%M}, {WEEKDAYS[local.weekday()]}, user timezone {timezone}."
    if owner:
        context += f" Card owner: {owner}."
    context += f" Reply language: {reply_language(text)}."
    return context
